90	/// Load the user's jj configuration the way the jj CLI does.
91	///
92	/// Layers, lowest to highest: jj-lib defaults, `/etc/jj` (unix),
93	/// `$JJ_CONFIG` (overrides system and user paths) or the user files
94	/// (`~/.jjconfig.toml`, `<config dir>/jj/config.toml` + `conf.d`),
95	/// the repo config (`.jj/repo/config.toml`), then `JJ_USER` /
96	/// `JJ_EMAIL` overrides. Deviation from the CLI: no command-line
97	/// layer and no `EnvBase` layer (debug / color / pager knobs that
98	/// only affect CLI presentation).
99	fn stacked_config(repo_config_path: Option<&Path>) -> Result<StackedConfig> {
100	    let mut config = StackedConfig::with_defaults();
101	    // Keys the engine reads whose defaults ship with the jj CLI's
102	    // config files rather than jj-lib's (values match jj 0.43).
103	    config.add_layer(ConfigLayer::parse(
104	        ConfigSource::Default,
105	        r#"
106	        [snapshot]
107	        auto-track = "all()"
108	        max-new-file-size = "1MiB"
109	        [git]
110	        auto-local-bookmark = false
111	        track-default-bookmark-on-clone = true
112	        "#,
113	    )?);
114	    let jj_config = std::env::var("JJ_CONFIG").ok();
115	
116	    if jj_config.is_none() && cfg!(unix) {
117	        load_file_if_exists(&mut config, ConfigSource::System, "/etc/jj/config.toml")?;
118	        load_dir_if_exists(&mut config, ConfigSource::System, "/etc/jj/conf.d")?;
119	    }
120	
121	    if let Some(paths) = &jj_config {
122	        for path in std::env::split_paths(paths).filter(|p| !p.as_os_str().is_empty()) {
123	            if path.is_dir() {
124	                config.load_dir(ConfigSource::User, path)?;
125	            } else {
126	                config.load_file(ConfigSource::User, path)?;
127	            }
128	        }
129	    } else {
130	        let home = home_dir();
131	        let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
132	            Some(x) if !x.is_empty() => Some(PathBuf::from(x)),
133	            _ => home.as_ref().map(|h| h.join(".config")),
134	        };
135	        if let Some(home) = &home {
136	            load_file_if_exists(&mut config, ConfigSource::User, home.join(".jjconfig.toml"))?;
137	        }
138	        if let Some(dir) = &config_dir {
139	            load_file_if_exists(&mut config, ConfigSource::User, dir.join("jj/config.toml"))?;
140	            load_dir_if_exists(&mut config, ConfigSource::User, dir.join("jj/conf.d"))?;
141	        }
142	    }
