    fn repo_and_config_dir(tag: &str) -> (PathBuf, PathBuf, PathBuf) {
        let base = crate::test_helpers::unique_base(tag);
        let repo = base.join("repo/.jj/repo");
        std::fs::create_dir_all(&repo).expect("create the stand-in .jj/repo");
